class Solution {
    private lateinit var power:LongArray;
    private var n=0;
    private var radius=0;
    private var budget=0L;
    private fun possible(target:Long):Boolean{
        val difference=LongArray(n+1);
        var active=0L;
        var used=0L;
        for(city in 0 until n){
            active+=difference[city];
            val need=target-power[city]-active;
            if(need>0){
                used+=need;
                if(used>budget)return false;
                active+=need;
                val station=minOf(n-1,city+radius);
                val expire=minOf(n,station+radius+1);
                difference[expire]-=need
            }
        };
        return true
    }
    fun maxPower(stations:IntArray,r:Int,k:Int):Long{
        n=stations.size;
        radius=r;
        budget=k.toLong();
        val prefix=LongArray(n+1);
        for(i in stations.indices)prefix[i+1]=prefix[i]+stations[i];
        power=LongArray(n){
            city->prefix[minOf(n,city+r+1)]-prefix[maxOf(0,city-r)]
        };
        var left=power.minOrNull()!!;
        var right=left+k;
        while(left<right){
            val middle=(left+right+1)/2;
            if(possible(middle))left=middle else right=middle-1
        };
        return left
    }
}

